select
  'cognitive-psychology',
  null,
  'Cognitive Psychology',
  'Cognitive Psychology',
  'Cognitive Psychology investigates how people perceive, attend, remember, represent knowledge, understand language, solve problems, reason, and choose. The course integrates classic experiments with contemporary cognitive neuroscience, computational modeling, open science, and real-world applications. A common conceptual spine serves both pathways: undergraduates build experimental literacy and transferable understanding; MA students add primary-literature synthesis, formal analysis, methodological critique, and independent research design.',
  $cogpjson${"slug": "cognitive-psychology", "title": "Cognitive Psychology", "description": "Cognitive Psychology investigates how people perceive, attend, remember, represent knowledge, understand language, solve problems, reason, and choose. The course integrates classic experiments with contemporary cognitive neuroscience, computational modeling, open science, and real-world applications. A common conceptual spine serves both pathways: undergraduates build experimental literacy and transferable understanding; MA students add primary-literature synthesis, formal analysis, methodological critique, and independent research design.", "topics": [{"id": "5f7e28c9-5183-4019-8882-11a2ed93d29c", "type": "topic", "title": "1. Foundations, History, and the Science of Cognition", "description": "Establishes how cognitive psychology turns unobservable mental processes into testable theories, linking classic debates to modern open and computational science.", "children": [{"id": "cc9e35f8-3410-4955-b943-c1272649b4ed", "type": "subtopic", "title": "Origins and paradigms", "children": [{"id": "4acf29bd-fa77-46d4-95b5-c29e34977aa2", "type": "concept", "title": "Introspection, behaviorism, and the cognitive revolution"}, {"id": "83dd82ce-c532-42dc-b7be-a76ab6c569e7", "type": "concept", "title": "Information-processing, connectionist, Bayesian, dynamical, and embodied perspectives"}, {"id": "bfc6090a-5f96-4b0f-8000-465d18392d5c", "type": "concept", "title": "Levels of explanation: computational, algorithmic, and implementational"}], "description": "Understand why the field moved from introspection and behaviorism toward information-processing and embodied approaches."}, {"id": "34c400a7-aecb-47fa-a988-0f743ac25f83", "type": "subtopic", "title": "Theory building and inference", "children": [{"id": "0270668c-91ff-45fe-84aa-78e86e7c72cc", "type": "concept", "title": "Construct validity and converging operations"}, {"id": "d750cdbf-c23b-48b3-b5ab-b03ecbc4a7cd", "type": "concept", "title": "Process models, mechanisms, and prediction"}, {"id": "72fa5e75-3684-4244-8700-41bf950e3a2c", "type": "concept", "title": "Dissociations, interactions, and model comparison"}], "description": "Learn how constructs such as attention or working memory are operationalized and compared."}, {"id": "51834bd4-1c75-4ca7-9522-60c80498275b", "type": "subtopic", "title": "Research integrity and open science", "children": [{"id": "bc463645-ad2f-4c3c-b0e6-b37b559dccf6", "type": "concept", "title": "Preregistration, registered reports, and transparent workflows"}, {"id": "64c7d3fc-c867-4bcd-8a5f-db5c51f15a68", "type": "concept", "title": "Power, effect sizes, uncertainty, and multiverse analysis"}, {"id": "68a2f2bf-78e7-442e-8b15-25f4de7f44c1", "type": "concept", "title": "Replication, publication bias, and generalizability"}], "description": "Build habits that make cognitive findings credible, cumulative, and reusable."}, {"id": "ef3348dd-9825-4ece-8ae4-7caece1e588e", "type": "subtopic", "title": "Ethics and inclusion", "children": [{"id": "70e8dfc1-9282-49b9-ab7e-b92473b7ab16", "type": "concept", "title": "Informed consent, deception, privacy, and data governance"}, {"id": "0cbfcb6d-eb46-41fc-a08e-d2739a6555de", "type": "concept", "title": "WEIRD samples, accessibility, and measurement invariance"}, {"id": "a0dca10b-655f-4d51-8cef-b80ba3416aa1", "type": "concept", "title": "Responsible claims about groups and cognitive ability"}], "description": "Recognize that task design, sampling, technology, and interpretation all carry ethical consequences."}]}, {"id": "d3e8be35-cd0d-4039-ab58-7734acd01128", "type": "topic", "title": "2. Methods, Measurement, and Computational Approaches", "description": "Provides the experimental and quantitative toolkit for distinguishing mental processes from task artifacts and fitting formal models to behavior.", "children": [{"id": "bb44587c-a4bf-4c5c-af1d-8c44cc23ae2c", "type": "subtopic", "title": "Behavioral experimentation", "children": [{"id": "b1e2aaef-2b89-42af-bf11-618fd1465f94", "type": "concept", "title": "Reaction time, accuracy, signal detection, and speed–accuracy tradeoffs"}, {"id": "98e6fd20-6a80-4a47-875e-7dccca410b90", "type": "concept", "title": "Factorial, within-subject, and mixed designs"}, {"id": "2b133058-5723-4be2-a530-7b52e485ce4a", "type": "concept", "title": "Counterbalancing, manipulation checks, and demand characteristics"}], "description": "Design tasks that isolate cognitive operations while controlling alternative explanations."}, {"id": "82e75b8e-f9bc-40c9-b434-cfcf49d290b2", "type": "subtopic", "title": "Psychophysics and measurement", "children": [{"id": "78f4c980-0d07-40f6-bf0b-7257aa47f7c0", "type": "concept", "title": "Thresholds and methods of limits, adjustment, and constant stimuli"}, {"id": "1ad5b9af-6f95-4e57-9835-fc9b9ea4237c", "type": "concept", "title": "Weber–Fechner and Stevens functions"}, {"id": "e0371337-9765-4400-9079-7e241ecd7029", "type": "concept", "title": "Signal detection theory: sensitivity, bias, ROC curves"}], "description": "Connect physical stimulation to subjective experience and decision criteria."}, {"id": "21e3bb9f-45fe-4fb5-89db-0dae007b1a7b", "type": "subtopic", "title": "Cognitive modeling", "children": [{"id": "510683f7-40b8-4693-acd2-7ffc8fdf5aff", "type": "concept", "title": "Drift-diffusion and evidence-accumulation models"}, {"id": "3ba582c1-b7b7-43af-9829-168ffc564848", "type": "concept", "title": "Reinforcement learning and Bayesian inference"}, {"id": "c0a72c7d-8967-4034-9e11-ce55ece5f6a1", "type": "concept", "title": "Model identifiability, recovery, predictive checks, and cross-validation"}], "description": "Translate verbal theories into explicit mechanisms that can be estimated and falsified."}, {"id": "6544beed-8dab-4c4b-9d0b-e016b74051fc", "type": "subtopic", "title": "Neural and process-tracing methods", "children": [{"id": "ecedbe3b-203d-4232-ba60-63c2f91a394c", "type": "concept", "title": "EEG/ERP, fMRI, lesion, eye-tracking, and pupillometry"}, {"id": "58609383-8c6d-44cd-b9d6-33dba8cd66eb", "type": "concept", "title": "TMS and causal inference"}, {"id": "cf520608-27f4-4d90-b1e4-8a89dba6be5c", "type": "concept", "title": "Multivariate pattern analysis and representational similarity"}], "description": "Use complementary measures to constrain when and where cognitive processes occur."}]}, {"id": "b3bb7262-5c1c-4a43-83d6-9fba3b75f576", "type": "topic", "title": "3. Perception and Pattern Recognition", "description": "Examines how sensory signals become stable, meaningful representations despite noise, ambiguity, and changing contexts.", "children": [{"id": "1577b66c-c32d-41c6-b7e8-c2154cb38269", "type": "subtopic", "title": "Bottom-up and top-down processing", "children": [{"id": "ddacc22f-ea52-4ba7-8699-18921f6b3b8b", "type": "concept", "title": "Feature detection and hierarchical processing"}, {"id": "48be3acc-1828-4897-9f6f-c3da8bcdd8e7", "type": "concept", "title": "Perceptual inference and predictive processing"}, {"id": "1eeb934b-ac6a-4ad1-ac7e-11d1d260b242", "type": "concept", "title": "Context, expectations, and perceptual set"}], "description": "Explain how sensory evidence and prior knowledge jointly shape perceptual experience."}, {"id": "4d4745d1-5e72-4f55-b571-d92734e19b7c", "type": "subtopic", "title": "Object and face recognition", "children": [{"id": "a93ef855-54eb-4f2f-95bb-a89a4b4fd294", "type": "concept", "title": "Template, feature, structural-description, and recognition-by-components accounts"}, {"id": "5f8f96fb-f2ef-4db1-9373-a76f36797bf6", "type": "concept", "title": "Viewpoint dependence and invariance"}, {"id": "c553c9a8-59c1-49ff-a954-30c3b0c70034", "type": "concept", "title": "Face inversion, expertise, and prosopagnosia"}], "description": "Compare accounts of how wholes, parts, and expertise support recognition."}, {"id": "46396a01-cbad-4cec-a673-0437e8f5f073", "type": "subtopic", "title": "Space, motion, and multisensory perception", "children": [{"id": "27938be9-1a35-4c3e-a9eb-113447c4cb6d", "type": "concept", "title": "Depth cues, optic flow, and motion"}, {"id": "00f786f3-f3d7-47ba-8a82-2cbf20062aed", "type": "concept", "title": "Auditory scene analysis and speech perception"}, {"id": "8ed50e75-124b-4de2-b55f-546a3b4b174d", "type": "concept", "title": "Multisensory integration, recalibration, and illusions"}], "description": "Understand how the brain integrates cues across modalities into coherent scenes and actions."}, {"id": "cc6f2297-9a19-4df0-abe4-5a2510499486", "type": "subtopic", "title": "Perception in the world", "children": [{"id": "09e75d59-189b-4cf5-8a95-b2987f5b7358", "type": "concept", "title": "Scene gist and visual search"}, {"id": "6896b978-4b6f-43d2-b56f-91c7734b3915", "type": "concept", "title": "Perception–action coupling and affordances"}, {"id": "0a1482d6-59ab-4c52-8631-df4c3e6493f0", "type": "concept", "title": "Expert performance, radiology, eyewitness observation, and design"}], "description": "Apply laboratory principles to complex, naturalistic environments."}]}, {"id": "81f0401e-4c75-4ce6-8aa7-93c6c3d872d3", "type": "topic", "title": "4. Attention and Cognitive Control", "description": "Explains how limited systems prioritize information, maintain goals, and coordinate action under distraction and multitasking.", "children": [{"id": "253cb69c-3a67-4012-ba34-3f5e86971536", "type": "subtopic", "title": "Selective attention", "children": [{"id": "66cc6d96-fa1e-469a-b02e-b681cf4904d1", "type": "concept", "title": "Dichotic listening and filter theories"}, {"id": "dc0f2382-853c-4e79-89b9-cd5c2502661f", "type": "concept", "title": "Spotlight, zoom-lens, feature integration, and biased competition"}, {"id": "452dc4bd-aaa6-4fdf-a968-b0b11285d43a", "type": "concept", "title": "Load theory and attentional capture"}], "description": "Compare early, late, and flexible-selection accounts of what gains access to processing."}, {"id": "5219d83a-307b-4f79-a459-4cf1ccfd3eb3", "type": "subtopic", "title": "Temporal attention and awareness", "children": [{"id": "04ff0c77-d36f-4fd3-a9bf-6971c76b9ee0", "type": "concept", "title": "Attentional blink and psychological refractory period"}, {"id": "63ce9636-fce3-47c7-91bc-6ebe98dd8496", "type": "concept", "title": "Inattentional and change blindness"}, {"id": "ba44c3f9-c8e4-48ed-956a-ebeeae6bf647", "type": "concept", "title": "Conscious access versus subliminal processing"}], "description": "Identify limits in selecting rapidly changing information."}, {"id": "d69906a5-d71b-4871-bf16-4706a00a4fbc", "type": "subtopic", "title": "Executive control", "children": [{"id": "6055ddd6-5ab7-4ab2-b10d-30284d5ccd7e", "type": "concept", "title": "Stroop, flanker, stop-signal, and task-switching paradigms"}, {"id": "e8f99cf6-55a7-4a28-a19d-e01bb045df6e", "type": "concept", "title": "Inhibition, updating, shifting, and proactive/reactive control"}, {"id": "ccb9f737-3dad-4ff8-aa68-32e1426fb8ab", "type": "concept", "title": "Conflict monitoring and error processing"}], "description": "Analyze how goals suppress habits, resolve conflict, and switch task sets."}, {"id": "790020b9-17d2-4bb9-b05f-3e1f1e90525b", "type": "subtopic", "title": "Applied attention", "children": [{"id": "4ac32fae-1dcd-44e2-8c0c-c57aaf488c10", "type": "concept", "title": "Multitasking and media use"}, {"id": "6cdb79c4-8fdf-4d4f-ab03-9a24bc6ebca2", "type": "concept", "title": "Vigilance, automation, and alarm design"}, {"id": "2ea6edd6-313c-484d-8405-9425c0bee45a", "type": "concept", "title": "Driving, aviation, education, and human factors"}], "description": "Use cognitive theory to improve safety and performance in high-demand settings."}]}, {"id": "69573aae-9de1-4eff-8138-eac06c68e690", "type": "topic", "title": "5. Working Memory and Mental Representation", "description": "Studies the short-term workspace that supports comprehension, reasoning, planning, and the active control of thought.", "children": [{"id": "3b47fe9c-266b-4441-b8ef-48fde6030e7f", "type": "subtopic", "title": "Architectures of working memory", "children": [{"id": "98a9d189-7734-4593-beaf-40a970794006", "type": "concept", "title": "Baddeley–Hitch model and episodic buffer"}, {"id": "f86cb125-c385-43b0-ad1a-fd37e7e7e1f6", "type": "concept", "title": "Cowan embedded-processes model"}, {"id": "15b9f28b-57f9-4bdb-bbc4-c8f25167b9eb", "type": "concept", "title": "Interference, decay, and resource accounts"}], "description": "Compare unitary capacity accounts with component and embedded-process models."}, {"id": "b5371490-755b-40b3-bf88-b55dcc25a473", "type": "subtopic", "title": "Capacity and individual differences", "children": [{"id": "6b1176e5-c70a-449b-b5f0-72f31d853e9b", "type": "concept", "title": "Span, complex span, n-back, and change-detection tasks"}, {"id": "03adf3a9-6975-491d-89b6-4d0ebacbaa6c", "type": "concept", "title": "Chunking, expertise, and strategy"}, {"id": "594c8bc3-0c59-46e7-9922-c94bf332156d", "type": "concept", "title": "Reliability, task impurity, and latent-variable approaches"}], "description": "Understand what working-memory measures capture and why performance varies."}, {"id": "067915af-3128-4ad6-ac22-f3d4d5e6b0eb", "type": "subtopic", "title": "Working memory in cognition", "children": [{"id": "f32f230d-e299-4594-8f98-cb66a5df815f", "type": "concept", "title": "Reading and language comprehension"}, {"id": "dccb72aa-4948-4720-92dc-bc64865b4acf", "type": "concept", "title": "Reasoning, mathematics, and problem solving"}, {"id": "09c323f8-cf75-4d17-8525-f063a8fdc357", "type": "concept", "title": "Visual imagery and mental rotation"}], "description": "Trace how temporary representations support other complex abilities."}, {"id": "daab7bc7-a7ff-4cbf-9917-f200cb8b12bc", "type": "subtopic", "title": "Training and translation", "children": [{"id": "4b500ce0-f87d-4c30-b17f-3ad6f0efb478", "type": "concept", "title": "Near versus far transfer"}, {"id": "e0090afd-f0b4-4ce4-89c6-55d265ca6a28", "type": "concept", "title": "Placebo and expectancy controls"}, {"id": "09060f22-9e98-4262-9b59-beb533940ded", "type": "concept", "title": "Educational, aging, and clinical applications"}], "description": "Evaluate claims that practice improves broad cognitive ability."}]}, {"id": "9af46545-16fd-46ff-94eb-3c0687fc0331", "type": "topic", "title": "6. Long-Term Memory: Encoding, Consolidation, and Retrieval", "description": "Explains how experiences become durable knowledge and how retrieval reconstructs rather than simply replays the past.", "children": [{"id": "14eec52e-2b6f-47bc-9d2a-04f5bc608361", "type": "subtopic", "title": "Memory systems", "children": [{"id": "a19f6b78-7f23-4cf9-a3ea-f3cb2bcd1e71", "type": "concept", "title": "Episodic, semantic, and autobiographical memory"}, {"id": "b9bf86c4-9fb6-4695-a9ea-68daeeae5882", "type": "concept", "title": "Procedural memory, priming, and conditioning"}, {"id": "ec976636-7289-4af9-bfa8-2a4ed87f5f6d", "type": "concept", "title": "Explicit/implicit and declarative/nondeclarative distinctions"}], "description": "Differentiate types of memory by content, awareness, neural basis, and behavioral signature."}, {"id": "4ed2cc1b-3df8-4e90-9414-b552b4d6e339", "type": "subtopic", "title": "Encoding and consolidation", "children": [{"id": "36602391-9405-4752-984d-12703adf869d", "type": "concept", "title": "Levels of processing, generation, distinctiveness, and elaboration"}, {"id": "4a00dbc0-8fb0-4536-8196-3064ce222da6", "type": "concept", "title": "Spacing, interleaving, retrieval practice, and desirable difficulties"}, {"id": "f447dbe5-1cc5-4607-9605-c50b1802bd95", "type": "concept", "title": "Systems and synaptic consolidation; sleep and memory"}], "description": "Identify the conditions that create durable, accessible traces."}, {"id": "befc2c0d-1e48-46be-ae26-299aaa19f550", "type": "subtopic", "title": "Retrieval", "children": [{"id": "21b42e3b-9524-4fe7-accc-d5bccd264041", "type": "concept", "title": "Encoding specificity and transfer-appropriate processing"}, {"id": "09f2f505-83af-43ac-a3b2-b60d02aac197", "type": "concept", "title": "Recall, recognition, familiarity, and recollection"}, {"id": "1135bb29-28cb-4031-9404-0956b07ed6e6", "type": "concept", "title": "Testing effects, retrieval-induced forgetting, and reconsolidation"}], "description": "Understand how cues, context, and goals determine what can be remembered."}, {"id": "ebd3a63d-2281-46f0-8019-1a6bd5b811ea", "type": "subtopic", "title": "Neural and lifespan perspectives", "children": [{"id": "49a41b86-e9e1-4054-9698-793258185473", "type": "concept", "title": "Hippocampus, medial temporal lobe, and cortical networks"}, {"id": "60430bdd-2928-4146-9521-2ecc97d825ae", "type": "concept", "title": "Amnesia and classic neuropsychological cases"}, {"id": "1622f3a3-c3cb-4804-a7c5-434c3aea457e", "type": "concept", "title": "Childhood development, aging, and compensatory strategies"}], "description": "Connect memory behavior to brain systems and developmental change."}]}, {"id": "d9db3eb6-6b34-4013-8661-1ada286d856e", "type": "topic", "title": "7. Forgetting, Memory Distortion, and Metamemory", "description": "Treats forgetting as both a limitation and an adaptive process, while showing why confidence and accuracy can diverge.", "children": [{"id": "d9a0ed74-eab6-4ab5-b3a1-e6de11035e1e", "type": "subtopic", "title": "Mechanisms of forgetting", "children": [{"id": "35a63efc-d22e-483c-b26d-cc93c49e5628", "type": "concept", "title": "Decay, interference, and cue overload"}, {"id": "6fa0f4ee-f128-470b-a214-39eaab5fa158", "type": "concept", "title": "Directed and motivated forgetting"}, {"id": "64a8adbe-8ec9-4d1d-b94f-bcb58f9ea03c", "type": "concept", "title": "Context drift and retrieval failure"}], "description": "Compare explanations based on trace change, competition, context, and failed access."}, {"id": "04562aee-b3a0-406a-a816-421ed6d3a4ec", "type": "subtopic", "title": "Constructive memory", "children": [{"id": "700c4f2b-d995-4caf-a69e-cc86c14e3afc", "type": "concept", "title": "Schemas, scripts, and source monitoring"}, {"id": "f47ae327-a08b-43d7-b1ba-c2db5ddf6277", "type": "concept", "title": "Misinformation, imagination inflation, and false-memory paradigms"}, {"id": "e8f3aea6-07b2-4d58-aa61-237c647c0ff4", "type": "concept", "title": "Gist, verbatim traces, and adaptive reconstruction"}], "description": "Explain how schemas and post-event information reshape recollection."}, {"id": "0814cd8d-02bc-4a45-9c92-5456c6439437", "type": "subtopic", "title": "Eyewitness memory", "children": [{"id": "9bf9b36c-e182-46cd-b27b-05874adbc335", "type": "concept", "title": "Lineup structure and administrator effects"}, {"id": "6886fb19-2230-4a14-823e-b239b98ff3c5", "type": "concept", "title": "Confidence–accuracy calibration and feedback"}, {"id": "aba85685-3f91-4482-b180-b4500946a981", "type": "concept", "title": "Cognitive interview and vulnerable witnesses"}], "description": "Apply memory science to interviews, identification, and legal evidence."}, {"id": "ae685274-4997-456b-af13-f143006ef16a", "type": "subtopic", "title": "Metamemory", "children": [{"id": "6ebeaecd-05da-4784-a613-5182e7238cf7", "type": "concept", "title": "Judgments of learning and feeling-of-knowing"}, {"id": "6faacfd4-817c-433a-97f0-2bef064365ee", "type": "concept", "title": "Calibration, illusions of competence, and fluency"}, {"id": "24093672-e32f-4b0f-8815-d0c6e7e6062a", "type": "concept", "title": "Study-time allocation and self-regulated learning"}], "description": "Study how people monitor and control their own learning and remembering."}]}, {"id": "30dd51e0-a6cb-4495-80f7-a64376b09ef5", "type": "topic", "title": "8. Knowledge, Concepts, and Semantic Organization", "description": "Explores how knowledge is structured so people can categorize new instances, draw inferences, and use experience efficiently.", "children": [{"id": "15338e4e-5bb6-4939-8b34-24f337326381", "type": "subtopic", "title": "Theories of concepts", "children": [{"id": "48256ccf-4d94-416c-99b5-1f913429b907", "type": "concept", "title": "Classical, prototype, exemplar, and theory-based accounts"}, {"id": "ed21173c-01a2-4598-ad31-a6864b239818", "type": "concept", "title": "Typicality, family resemblance, and graded membership"}, {"id": "06f6cc95-2b24-4777-9004-06ed81c427eb", "type": "concept", "title": "Ad hoc and goal-derived categories"}], "description": "Compare representations based on definitions, central tendency, remembered cases, and causal structure."}, {"id": "8e2a47df-7f43-4b58-8025-d60d82010587", "type": "subtopic", "title": "Semantic memory", "children": [{"id": "5dfe8851-44a1-48c9-9b09-b52dfe47a084", "type": "concept", "title": "Hierarchical and spreading-activation networks"}, {"id": "232f221b-169f-46b1-95f7-fb2facaf70b8", "type": "concept", "title": "Feature-based and distributional representations"}, {"id": "0aa5032e-0078-4da6-ae16-d7a5f577bde1", "type": "concept", "title": "Semantic priming and hub-and-spoke accounts"}], "description": "Model how concepts and relations are organized and accessed."}, {"id": "e43739f8-3639-478a-9c17-24552b6431e9", "type": "subtopic", "title": "Grounded and embodied knowledge", "children": [{"id": "6b5253ef-b257-4a62-a152-4e89094e2610", "type": "concept", "title": "Sensorimotor simulation"}, {"id": "b94d9bf9-96c5-4623-9992-a7c7f6d9e4b5", "type": "concept", "title": "Abstract concepts and metaphor"}, {"id": "892c40d6-1d42-404e-8f36-2a2a973ae079", "type": "concept", "title": "Challenges to strong embodiment"}], "description": "Ask whether conceptual content depends on perceptual and motor systems."}, {"id": "648e17db-50ab-4167-83e7-c532b3a9f506", "type": "subtopic", "title": "Culture and expertise", "children": [{"id": "d1b095f2-241e-4e10-91d7-04683d9a0513", "type": "concept", "title": "Expert categorization and perceptual learning"}, {"id": "83057e18-95bd-45c2-b54b-92337a67110e", "type": "concept", "title": "Linguistic relativity and cultural variation"}, {"id": "0bfc7861-b523-41f4-b5ca-11831ef527ff", "type": "concept", "title": "Category learning, induction, and transfer"}], "description": "Understand how learning histories and cultural practices shape category boundaries."}]}, {"id": "e59bce09-1e71-4721-807a-c9fdfaeaedd2", "type": "topic", "title": "9. Language, Reading, and Psycholinguistics", "description": "Investigates how minds map sounds and symbols to structured meaning during real-time comprehension and production.", "children": [{"id": "eaabecde-dbe6-442e-b847-b86082bad571", "type": "subtopic", "title": "Language architecture", "children": [{"id": "4db39cf1-3c2d-43d0-b9de-7115b183ecee", "type": "concept", "title": "Phonology, morphology, syntax, semantics, and pragmatics"}, {"id": "473d1dda-5c04-4852-bf54-3dbfb2ba2ccc", "type": "concept", "title": "Compositionality and recursion"}, {"id": "8cd7bd6c-57fc-48df-adbd-e66f4ae251fe", "type": "concept", "title": "Descriptive versus prescriptive grammar"}], "description": "Understand the representational levels that make language productive."}, {"id": "f034bc78-75d6-44c1-a58e-166954930401", "type": "subtopic", "title": "Word recognition and reading", "children": [{"id": "e7f3ac0f-caac-435d-b36a-9225565054ea", "type": "concept", "title": "Cohort, TRACE, and interactive-activation models"}, {"id": "d9a0f363-fe30-445f-b2f9-4bc57866c2a8", "type": "concept", "title": "Lexical decision, frequency, neighborhood, and priming effects"}, {"id": "e0700344-860b-46e8-a828-3da477364955", "type": "concept", "title": "Dual-route and connectionist accounts of reading"}], "description": "Explain how visual and spoken inputs activate lexical knowledge."}, {"id": "09b8f235-9f6a-48dd-af55-02964eb1c47c", "type": "subtopic", "title": "Sentence and discourse processing", "children": [{"id": "c1227844-e7f9-4898-b76a-87bd307ed8d9", "type": "concept", "title": "Parsing, garden paths, and constraint-based processing"}, {"id": "a203a5f0-5cc4-4601-91d3-3bc9e8aa1b58", "type": "concept", "title": "Reference, inference, and discourse coherence"}, {"id": "b9c79c89-c66b-40e4-acc4-1b88ce110feb", "type": "concept", "title": "Eye movements and incremental comprehension"}], "description": "Study how people resolve ambiguity and build situation models online."}, {"id": "3cd715aa-a559-4f10-92fb-929dc226dede", "type": "subtopic", "title": "Production, acquisition, and diversity", "children": [{"id": "b9913f2c-fea3-4c3c-ab24-a13bbcc84b6b", "type": "concept", "title": "Lexical access, slips, monitoring, and dialogue"}, {"id": "1497c098-b18a-4948-b76a-8d3aaeae80a7", "type": "concept", "title": "Statistical learning and language development"}, {"id": "142d21fb-385f-41c7-9d2b-54f230e5a09b", "type": "concept", "title": "Bilingual control, sign language, aphasia, and dyslexia"}], "description": "Connect speaking and learning to bilingualism and language variation."}]}, {"id": "7bc13ca0-b784-416e-ae0a-902a06e18dfb", "type": "topic", "title": "10. Problem Solving, Expertise, and Creativity", "description": "Examines how people represent goals, search solution spaces, overcome impasses, and generate ideas that are both novel and useful.", "children": [{"id": "9c5d4898-9107-46b1-b498-c7e8f0343c4c", "type": "subtopic", "title": "Problem representation and search", "children": [{"id": "3ed3e635-4405-4be3-b2f8-c81748111c8d", "type": "concept", "title": "Problem spaces, operators, means–ends analysis"}, {"id": "91bdf0e7-448e-4da6-bfee-9f6831a96fa1", "type": "concept", "title": "Algorithms, heuristics, and hill climbing"}, {"id": "3f83ff7a-f861-423f-957d-dad8a9311e1a", "type": "concept", "title": "Insight, restructuring, and incubation"}], "description": "See why the way a problem is encoded can determine whether it is solvable."}, {"id": "7b10ff4d-5906-4210-9974-994a7904ab93", "type": "subtopic", "title": "Analogical reasoning", "children": [{"id": "f4bf4a59-ea7a-4db6-80b8-75ea9ee9e451", "type": "concept", "title": "Retrieval, mapping, and adaptation"}, {"id": "4f737992-6f04-47b2-bf9c-49d705cbb47a", "type": "concept", "title": "Surface similarity versus structural alignment"}, {"id": "12fd2771-ecfd-4511-aa7c-3d958887ef10", "type": "concept", "title": "Case-based reasoning and instruction"}], "description": "Understand how relational structure transfers learning across situations."}, {"id": "cc85c2d0-35d6-4cff-9439-1d9942a1984b", "type": "subtopic", "title": "Expertise", "children": [{"id": "3fe8f326-2e4c-4c13-8796-529d1cb40e82", "type": "concept", "title": "Chunking, deliberate practice, and pattern recognition"}, {"id": "679b74c9-77d6-4d31-9159-bd218d1194a9", "type": "concept", "title": "Adaptive expertise and transfer"}, {"id": "02fc5e24-80e7-47a8-bc21-2ba3547bc557", "type": "concept", "title": "Limits, bias, and the Einstellung effect"}], "description": "Explain how extensive practice reorganizes knowledge and performance."}, {"id": "c5ef724f-8be7-483d-8f15-5191d38af012", "type": "subtopic", "title": "Creativity", "children": [{"id": "cf5ca811-a678-427b-949c-1b1e8a231103", "type": "concept", "title": "Divergent and convergent thinking"}, {"id": "eea19fbe-3179-4162-a667-6c8127ac8689", "type": "concept", "title": "Associative search and executive control"}, {"id": "5e4ad399-0eb0-4c93-ab8c-0c60215a1bd7", "type": "concept", "title": "Measurement, collaboration, and constraints"}], "description": "Evaluate cognitive and social mechanisms that support original production."}]}, {"id": "a6c682b3-4d77-4b48-8554-e2548fc2c255", "type": "topic", "title": "11. Reasoning and Rationality", "description": "Studies how people derive conclusions, test hypotheses, and depart from—or appropriately adapt—formal norms.", "children": [{"id": "0394c366-2350-44ee-8378-8c573a508491", "type": "subtopic", "title": "Deductive reasoning", "children": [{"id": "1b229592-1fb0-4829-8bb4-b42ba5d55a43", "type": "concept", "title": "Syllogisms, conditionals, and Wason selection"}, {"id": "b852ca40-83a5-41e5-8c96-becad21e9787", "type": "concept", "title": "Mental logic and mental models"}, {"id": "67bedaab-3359-4910-82b4-d13a7843f300", "type": "concept", "title": "Belief bias and content effects"}], "description": "Compare formal validity with the mental processes used to evaluate arguments."}, {"id": "84a18228-a76d-4e17-b0dc-e086fbb2b0e9", "type": "subtopic", "title": "Inductive and causal reasoning", "children": [{"id": "6a53fdd3-09c1-4470-a373-7513ba3eb279", "type": "concept", "title": "Similarity, diversity, and category-based induction"}, {"id": "2015cc4e-a472-44d8-981b-2ea201ab48fc", "type": "concept", "title": "Covariation, interventions, and causal models"}, {"id": "e36338dd-5222-4dde-83df-0ddecaa9e8b1", "type": "concept", "title": "Bayesian updating and base rates"}], "description": "Understand how evidence supports generalization and causal explanation."}, {"id": "ca8f79b2-36bb-400c-ab0c-df4cd1e09f3d", "type": "subtopic", "title": "Dual-process and alternative accounts", "children": [{"id": "585831d0-1e09-40c6-a3ae-4dface2778eb", "type": "concept", "title": "Type 1/Type 2 frameworks"}, {"id": "b6041ae2-a79a-46ff-9050-fc9dbf12bba6", "type": "concept", "title": "Conflict detection and cognitive reflection"}, {"id": "e663dd30-a1ee-4a49-89ea-1fd48628d847", "type": "concept", "title": "Ecological and resource-rational perspectives"}], "description": "Evaluate claims about fast intuitive and slower reflective processing."}, {"id": "a1a3b519-475a-4cce-b2d7-2bbe79845886", "type": "subtopic", "title": "Scientific reasoning", "children": [{"id": "6ad419b3-54d9-4a6b-b274-e45af529cd26", "type": "concept", "title": "Confirmation bias and motivated reasoning"}, {"id": "a89a3242-d2a5-44f9-b763-f871f890eb4a", "type": "concept", "title": "Hypothesis testing and explanation"}, {"id": "502d9a8b-2f73-48df-8d08-e9f688287c6a", "type": "concept", "title": "Misinformation correction and intellectual humility"}], "description": "Apply cognitive principles to evidence evaluation and belief revision."}]}, {"id": "47c60452-0252-4ca9-8a30-e0091f599416", "type": "topic", "title": "12. Judgment, Decision-Making, and Choice", "description": "Explains choices under risk, uncertainty, time pressure, and social influence, bridging laboratory findings with policy and design.", "children": [{"id": "ab216c70-effc-4a75-aa81-e4cd97ebfac0", "type": "subtopic", "title": "Normative foundations", "children": [{"id": "f8fa3090-589d-4eba-a71d-fcea9d82bb27", "type": "concept", "title": "Expected value, expected utility, and Bayesian decision theory"}, {"id": "9ce74f42-41ed-4b45-9d88-4fc7fbc17595", "type": "concept", "title": "Dominance, transitivity, and calibration"}, {"id": "3fba81d9-e9b6-4061-890e-26b3ff537484", "type": "concept", "title": "Risk, ambiguity, and uncertainty"}], "description": "Use formal benchmarks to describe coherent choice without assuming they fully describe human behavior."}, {"id": "37227b79-29f3-48ee-be85-28beb4ae22ec", "type": "subtopic", "title": "Descriptive theories", "children": [{"id": "8fd043f4-0acb-42ed-8668-4a5e130a3113", "type": "concept", "title": "Prospect theory, loss aversion, and reference dependence"}, {"id": "9b53c162-ae64-4dce-8959-fe7bb3398a87", "type": "concept", "title": "Framing, endowment, and status quo effects"}, {"id": "df31e7c8-5803-4530-9696-c969dcc48efb", "type": "concept", "title": "Probability weighting and mental accounting"}], "description": "Model systematic patterns that depart from classical rational-choice assumptions."}, {"id": "620d5498-90de-4668-9f10-c439331770b2", "type": "subtopic", "title": "Heuristics and biases", "children": [{"id": "d5ad9745-1321-4e4e-bf6e-0c7bedb7ed28", "type": "concept", "title": "Availability, representativeness, anchoring, and affect"}, {"id": "1c35c8a0-b153-4806-80ff-9a3a6df1679f", "type": "concept", "title": "Base-rate neglect, conjunction, and overconfidence"}, {"id": "1b5eaee2-9c98-4f3d-b28c-5ffcfdd6af8a", "type": "concept", "title": "Fast-and-frugal and ecological rationality accounts"}], "description": "Distinguish useful shortcuts from predictable error."}, {"id": "a5292dba-cf1d-45ec-af9c-31dc1276141a", "type": "subtopic", "title": "Choice architecture and ethics", "children": [{"id": "fd538440-224b-4428-ae1c-1b542cdc5b30", "type": "concept", "title": "Defaults, nudges, boosts, and debiasing"}, {"id": "6fd32551-f5dc-49f6-b894-8eb38155d2a1", "type": "concept", "title": "Intertemporal and medical decisions"}, {"id": "3338f218-5f55-4820-bc00-8a4eab7797b3", "type": "concept", "title": "Algorithmic advice, fairness, and informed consent"}], "description": "Design decision environments while respecting autonomy and distributional effects."}]}, {"id": "1c9c156d-1b4b-4307-814d-9ed36e3cad81", "type": "topic", "title": "13. Cognitive Development, Aging, and Individual Differences", "description": "Places cognitive mechanisms in developmental and lifespan context and examines why people follow different cognitive trajectories.", "children": [{"id": "8f96ec81-4da6-4ebe-b761-2cdc7b89ea65", "type": "subtopic", "title": "Developmental mechanisms", "children": [{"id": "536065f9-ea10-4d85-b629-fdcf1ced4ac1", "type": "concept", "title": "Core knowledge, constructivist, information-processing, and sociocultural views"}, {"id": "c1c02a15-cb92-4650-8621-e92dde1b5eb9", "type": "concept", "title": "Executive function and metacognition"}, {"id": "1457e220-355d-49f5-906c-5fd64f7914be", "type": "concept", "title": "Language, numerical cognition, and theory of mind"}], "description": "Explain change through maturation, learning, social input, and representational growth."}, {"id": "cc01a469-74ef-4851-89d0-8bdb4451a105", "type": "subtopic", "title": "Cognitive aging", "children": [{"id": "96352f45-87f6-4444-a6dc-62de58fbfea1", "type": "concept", "title": "Processing speed, inhibition, and working memory"}, {"id": "2f004296-3ee7-4464-9311-c346d4648ee9", "type": "concept", "title": "Episodic versus semantic change"}, {"id": "97232b62-e346-4e83-9a9e-513f6b644c5a", "type": "concept", "title": "Cognitive reserve, compensation, and intervention"}], "description": "Distinguish decline, stability, and compensation across cognitive systems."}, {"id": "ef8ac985-f12b-46a8-87f5-28f2b5f832d0", "type": "subtopic", "title": "Individual differences", "children": [{"id": "9f3379d4-7344-4b53-b39e-5d17eb0067c4", "type": "concept", "title": "Intelligence, executive function, and latent structure"}, {"id": "636b6b45-7e4e-4729-986c-19692ea64e0c", "type": "concept", "title": "Reliability, validity, and measurement invariance"}, {"id": "0dd04a45-7bbd-4aea-b74e-6c2b477396dc", "type": "concept", "title": "Motivation, affect, sleep, stress, and health"}], "description": "Evaluate what cognitive tests measure and how traits relate across tasks."}, {"id": "50128b41-40a1-41b7-b191-b6064f6d8efc", "type": "subtopic", "title": "Neurodiversity and accessibility", "children": [{"id": "1608f386-50f2-4fb9-b2fd-3c05b2dd966a", "type": "concept", "title": "ADHD, autism, dyslexia, and heterogeneous profiles"}, {"id": "113d47cd-cd55-4c49-a03c-66930d88153c", "type": "concept", "title": "Universal design and accommodations"}, {"id": "bf26eef3-2b01-45d7-8fdb-df38a6fa6e68", "type": "concept", "title": "Strengths-based and participatory research"}], "description": "Use variation to improve theory and inclusive design without reducing people to deficits."}]}, {"id": "514dd012-3bb5-4dfd-8730-f1daf80ece3b", "type": "topic", "title": "14. Cognitive Neuroscience and Consciousness", "description": "Links cognitive functions to distributed brain systems while treating neural evidence as one level of explanation rather than a replacement for behavior.", "children": [{"id": "f12516be-0eca-424b-8666-bf8871584ae5", "type": "subtopic", "title": "Mapping cognition to brain systems", "children": [{"id": "e4637470-5517-4402-bc08-554145bde101", "type": "concept", "title": "Lesion evidence, dissociations, and network neuroscience"}, {"id": "60231b9a-5d93-4eca-a8e0-dc1f5380b3b2", "type": "concept", "title": "Reverse inference and construct validity"}, {"id": "b95e1f9b-8547-4679-be85-48899974b4a7", "type": "concept", "title": "Connectivity, dynamics, and distributed representation"}], "description": "Learn what localization can and cannot establish about mental mechanisms."}, {"id": "39c8701d-bae9-4045-8e3d-fc34cb444146", "type": "subtopic", "title": "Methods and causal claims", "children": [{"id": "79067ba9-ca27-4bd1-a853-1c27d85cea4d", "type": "concept", "title": "EEG/MEG, fMRI, intracranial recording, and lesion methods"}, {"id": "105498f0-a1b8-4a4d-908c-5a1cbe295234", "type": "concept", "title": "TMS, stimulation, and perturbation"}, {"id": "3b787a47-5135-4d16-ad37-030ca5e13d2e", "type": "concept", "title": "Decoding, encoding models, and replication"}], "description": "Critically compare the temporal, spatial, and inferential strengths of major tools."}, {"id": "af13b7c5-5ac6-4c0b-ba66-2e64274a9abd", "type": "subtopic", "title": "Consciousness", "children": [{"id": "f96822e7-f34d-4c17-9f3b-010d880de938", "type": "concept", "title": "Global workspace, recurrent processing, and higher-order theories"}, {"id": "2af6fbe2-e6ad-4382-8031-2f6d94948549", "type": "concept", "title": "Masking, binocular rivalry, and no-report paradigms"}, {"id": "c1c5eb57-c61f-4def-bacd-ca8d1b195de7", "type": "concept", "title": "Awareness, attention, confidence, and metacognition"}], "description": "Evaluate competing accounts of conscious access and subjective experience."}, {"id": "18e2509e-937a-44e2-8cdb-af80814e118f", "type": "subtopic", "title": "Clinical and altered cognition", "children": [{"id": "a6a33ec7-f9c8-4d6d-8e5d-5ee5b8c1d804", "type": "concept", "title": "Neglect, agnosia, amnesia, aphasia, and executive syndromes"}, {"id": "86833e49-ba18-4435-b467-59f1b5756702", "type": "concept", "title": "Anesthesia, sleep, and disorders of consciousness"}, {"id": "1de288fe-f296-4dd7-9ebf-35f8257c8d57", "type": "concept", "title": "Ethical communication of neural findings"}], "description": "Use neurological and psychiatric variation to test cognitive architecture."}]}, {"id": "917786fa-ae74-4e69-8016-5f11016e2abc", "type": "topic", "title": "15. Applied, Socially Situated, and Human–AI Cognition", "description": "Extends cognitive principles beyond isolated laboratory tasks to education, work, technology, culture, and collaborative intelligence.", "children": [{"id": "ac3c0294-01c9-4c98-95c1-cb44c07264da", "type": "subtopic", "title": "Learning and education", "children": [{"id": "40f759cc-4bda-49f6-afb1-692f82b9f504", "type": "concept", "title": "Retrieval practice, spacing, interleaving, and feedback"}, {"id": "04c29297-b439-40f7-b6ce-725c206c5356", "type": "concept", "title": "Cognitive load and multimedia learning"}, {"id": "8f5f4611-4ec4-4ede-b63c-ae9d1142bcdf", "type": "concept", "title": "Self-explanation, calibration, and transfer"}], "description": "Translate memory and metacognition research into durable, equitable learning practices."}, {"id": "d26f5fec-533c-4bba-bc1e-d88bcdbbd5d2", "type": "subtopic", "title": "Human factors and distributed cognition", "children": [{"id": "20e5031c-e2d3-4fcc-a309-9afebcc61666", "type": "concept", "title": "Situation awareness and decision support"}, {"id": "b33e1819-64f1-4380-b88d-45fcc6a34aeb", "type": "concept", "title": "External memory, visualization, and interface design"}, {"id": "d568c416-5065-4c68-9693-a846a2e00cfc", "type": "concept", "title": "Teams, interruptions, and safety-critical systems"}], "description": "Analyze cognition as coordinated across people, artifacts, and environments."}, {"id": "5c2836a1-82d9-40ca-a5d9-90de1e5d51d8", "type": "subtopic", "title": "Culture, emotion, and social context", "children": [{"id": "8090a3b8-5557-40a5-9818-321a47ea8b19", "type": "concept", "title": "Emotion–attention and emotion–memory interactions"}, {"id": "046fa0d9-feff-4b6a-b687-bca548693e99", "type": "concept", "title": "Social cognition and motivated cognition"}, {"id": "1c667f8f-1d5f-4bd2-a9bd-288b9eadc497", "type": "concept", "title": "Cross-cultural task validity and context sensitivity"}], "description": "Examine how cognition changes with goals, affect, identity, and cultural practice."}, {"id": "c8913f2d-98d0-4389-b36c-d1958783e50c", "type": "subtopic", "title": "Human–AI cognition", "children": [{"id": "baf4ee32-7ecf-4f83-8617-5ddaa02f502e", "type": "concept", "title": "Automation bias, algorithm aversion, and calibrated trust"}, {"id": "deb43a54-1afe-4a7a-9a1d-249c0b0ae3a0", "type": "concept", "title": "Cognitive offloading, deskilling, and collaborative problem solving"}, {"id": "f95cf292-1627-4e23-8f66-f487b1cfcfd5", "type": "concept", "title": "Explainability, bias, privacy, authorship, and responsible use"}], "description": "Evaluate how generative and predictive systems alter judgment, learning, creativity, and responsibility."}]}], "dbBacked": true}$cogpjson$::jsonb,
